// Ingredient rats — 146 ingredient icons (24x24, one 1.5 outline in var(--outline), 2-4 flat fills, round pink-lined ears,
// dot eyes, pink nose). Every colour is a CSS custom property: put IR_TOKENS.light / IR_TOKENS.dark on :root (or any ancestor)
// for the active theme and include IR_CSS once. In dark the icons get a 1px flat lilac halo (--ir-halo) so the dark outline
// stays visible on the dark page. No dependencies. Usage: el.innerHTML = ingredientRat('potato', 'my-class').
// Generated by the ingredient-rats build script (markup is macro/dictionary packed; expanded once at import).

export const IR_CSS = `
.ir .o{stroke:var(--outline);stroke-width:1.5;stroke-linejoin:round;stroke-linecap:round}
.ir .ln{fill:none;stroke:var(--outline);stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
.ir .thin{fill:none;stroke-width:1.1;stroke-linecap:round;stroke-linejoin:round}
.ir .tailo{fill:none;stroke:var(--outline);stroke-width:3.4;stroke-linecap:round}
.ir .tail{fill:none;stroke:var(--pink);stroke-width:1.6;stroke-linecap:round}
.ir .ink{fill:var(--outline)}.ir .pink{fill:var(--pink)}.ir .nose{fill:var(--nose)}.ir .fur{fill:var(--fur)}
.ir{filter:var(--ir-halo,none)}
`;

