const N=v=>String(+v.toFixed(1)).replace(/^(-?)0\./,'$1.');
const X=s=>s
.replace(/\{t([^}]+)\}/g,(m,d)=>`<path class="tailo" d="${d}"/><path class="tail" d="${d}"/>`)
.replace(/\{e(\S+) (\S+) (\S+) (\S+)\}/g,(m,f,x,y,r)=>`<circle class="o" style="fill:var(--${f})" cx="${x}" cy="${y}" r="${r}"/><circle class="pink" cx="${x}" cy="${N(+y+r*.12)}" r="${N(r*.52)}"/>`)
.replace(/\{y(\S+) (\S+) (\S+) (\S+)\}/g,(m,a,b,y,r)=>`<circle class="ink" cx="${a}" cy="${y}" r="${r}"/><circle class="ink" cx="${b}" cy="${y}" r="${r}"/>`)
.replace(/\{p([^§]*)§([^§]*)§([^}]+)\}/g,(m,a,b,d)=>`<path ${a}${a?' ':''}d="${d}"/><path ${b}${b?' ':''}d="${d}"/>`)
.replace(/\{n(\S+) (\S+)\}/g,(m,x,y)=>`<ellipse class="nose o" style="stroke-width:.9" cx="${x}" cy="${y}" rx="1.3" ry="1"/>`);
const D = [['!','" style="fill:var(--'],['#','<ellipse class="o pink" style="stroke-width:1.1"'],['$','<path class='],['%','stroke-width:1'],['&','" cy="'],['*','<ellipse class="'],['+','"fill:none;stroke:var(--'],['?','"/>'],['@','" rx="'],['[','" d="M'],[']',' style='],['^','" ry="'],['_','" cx="'],['|','<circle cx="'],['~','"fill:var(--'],['¡','<g transform="matrix'],['¢','"thin"]"stroke:var(-'],['£','circle class='],['¤','" transform="rotate('],['¥','<rect class="o!b'],['¦','" height="'],['¨','" r=".'],['©','" width='],['ª','"]"stroke-width:'],['«','<circle]~b3-'],['¬','" r="2'],['®','<ellipse cx='],['¯','"o!b2-'],['°','"o!b4-'],['±','"§style=+b'],['²','"o!b1-'],['³','" r="1'],['µ','3.2?|3.9&11.8¬.6?|20.1&11.8¬.6?|6.6&15¬.8?|17.4&15¬.8?|12&10.8'],['¶','" y="1'],['·','"o!b3-']];
