/** ingredientId -> inner SVG markup */
export const INGREDIENT_RATS = Object.fromEntries(Object.entries(P).map(([k, v]) => [k, U(v)]));

/** '<svg class="ir …">…</svg>' for a known ingredient id, '' otherwise */
export const ingredientRat = (id, cls = '') => {
  const art = Object.hasOwn(INGREDIENT_RATS, id) ? INGREDIENT_RATS[id] : '';
  return art ? `<svg class="${('ir ' + cls).trim()}" viewBox="0 0 24 24" aria-hidden="true" focusable="false">${art}</svg>` : '';
};
